// Normaliza el evento de Culqi y extrae email + plan según el monto
const AMOUNT_TO_PLAN = {
  19000: 'pro',      // Profesional mensual S/190
  190000: 'pro',     // Profesional anual S/1900
  75000: 'empresa',  // Empresa mensual S/750
  750000: 'empresa'  // Empresa anual S/7500
};
const OK_EVENTS = /(succeeded|successful|aprob|paid|creado)/i;

const out = [];
for (const item of $input.all()) {
  const b = item.json.body ?? item.json ?? {};
  const evName = b.event || b.event_name || b.type || '';
  const charge = b.data || b.charge || (b.object && b.object.charge) || {};

  const amount = Number(charge.amount || b.amount || 0);
  const plan = AMOUNT_TO_PLAN[amount];
  const email = String(
    (charge.metadata && charge.metadata.email) ||
    (b.metadata && b.metadata.email) ||
    charge.email || ''
  ).toLowerCase().trim();

  const succeeded = OK_EVENTS.test(evName) || (!evName && amount > 0);

  if (succeeded && plan && email.includes('@')) {
    out.push({ json: { email, plan, amount, eventId: b.id || '', event: evName } });
  } else if (succeeded) {
    console.log('Culqi: evento OK sin email/plan reconocible', JSON.stringify(b).slice(0, 500));
  }
}
return out;

// Une el doc del usuario con el plan detectado en el webhook
const found = $input.all();
if (!found.length) return [];
return [{
  json: Object.assign({}, found[0].json, {
    plan: $('Parse Culqi').item.json.plan,
    planUpdatedAt: Date.now()
  })
}];
